<template><el-dialog v-model="visible" title="建立加工批次" width="min(650px,94vw)" :close-on-click-modal="false"><el-form label-width="120px" :disabled="busy"><el-form-item label="工厂"><el-select v-model="factoryId" :disabled="!admin" fit-input-width @change="factoryChanged"><el-option v-for="o in factories" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item><el-form-item label="生产工单"><el-select v-model="form.workOrderId" fit-input-width @change="orderChanged"><el-option v-for="o in orders" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item><el-form-item label="产品明细"><el-select v-model="form.itemId" fit-input-width @change="form.processId=''"> <el-option v-for="(o,i) in items" :key="o.id" :label="o.snapshot.name+' '+(i+1)+'（'+o.quantity+'件）'" :value="o.id"/></el-select></el-form-item><el-form-item label="工序"><el-select v-model="form.processId" fit-input-width><el-option v-for="o in processes" :key="o.processId" :label="o.processName" :value="o.processId"/></el-select></el-form-item><el-form-item label="加工数量"><el-input v-model.number="form.plannedQuantity" inputmode="numeric"/></el-form-item></el-form><template #footer><el-button :disabled="busy" @click="visible=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">确认</el-button></template></el-dialog></template>
<script setup lang="ts">
import {createUUID} from '@/utils/uuid'
import{ref,reactive,computed}from'vue';import{ElMessage}from'element-plus';import useUserStore from '@/store/modules/user';import{warehouseOptions,warehouseSave,type Row}from'@/api/metal/warehouse';import{orderDetail}from'@/api/metal/work-order';
const emit=defineEmits(['saved']),visible=ref(false),busy=ref(false),factoryId=ref(''),factories=ref<Row[]>([]),orders=ref<Row[]>([]),items=ref<Row[]>([]),form=reactive<Row>({}),admin=computed(()=>String(useUserStore().id)==='1'),processes=computed(()=>items.value.find(o=>o.id===form.itemId)?.plans??[]);
async function factoryChanged(){form.workOrderId='';form.itemId='';form.processId='';items.value=[];orders.value=(await warehouseOptions('work-orders',factoryId.value)).data}
async function orderChanged(){form.itemId='';form.processId='';items.value=(await orderDetail(form.workOrderId)).data.items}
async function open(factory?:string){Object.assign(form,{requestId:createUUID(),workOrderId:'',itemId:'',processId:'',plannedQuantity:1});factories.value=(await warehouseOptions('factories')).data;factoryId.value=factory||(!admin.value?factories.value[0]?.id:'')||'';if(factoryId.value)await factoryChanged();else{orders.value=[];items.value=[]}visible.value=true}
async function save(){if(!form.workOrderId||!form.itemId||!form.processId||!Number.isInteger(form.plannedQuantity)||form.plannedQuantity<1){ElMessage.error('请选择工单、产品、工序并填写正整数加工数量');return}busy.value=true;try{await warehouseSave('process-batch',form);visible.value=false;ElMessage.success('加工批次已建立');emit('saved')}finally{busy.value=false}}
defineExpose({open})
</script>